import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import { subscriptions } from 'kea-subscriptions'

import { objectsEqual } from 'lib/utils/objects'

import type { PersonListItemApi } from '../../generated/api.schemas'
import { PersonRange, personRange, readPerson } from '../shared/personReads'
import { readOrFailure } from '../shared/readOrFailure'
import { shellScopeLogic } from '../shell/shellScopeLogic'

export interface PersonScopeLabelLogicProps {
    personId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface personScopeLabelLogicValues {
    dateFrom: string // shellScopeLogic
    dateTo: string | null // shellScopeLogic
    filterTestAccounts: boolean // shellScopeLogic
    person: PersonListItemApi | null
    range: PersonRange
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface personScopeLabelLogicActions {
    personRead: (person: PersonListItemApi | null) => {
        person: PersonListItemApi | null
    }
    readPerson: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface personScopeLabelLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        range: (dateFrom: string, dateTo: string | null, filterTestAccounts: boolean) => PersonRange
    }
}

export type personScopeLabelLogicType = MakeLogicType<
    personScopeLabelLogicValues,
    personScopeLabelLogicActions,
    PersonScopeLabelLogicProps,
    personScopeLabelLogicMeta
>

/** The person a list is scoped to, read in the shell's range. Null while reading, or when the range does not hold them. */
export const personScopeLabelLogic = kea<personScopeLabelLogicType>([
    props({} as PersonScopeLabelLogicProps),
    key((props) => props.personId),
    path((key) => ['products', 'ai_observability', 'frontend', 'redesign', 'lists', 'personScopeLabelLogic', key]),
    connect(() => ({ values: [shellScopeLogic, ['dateFrom', 'dateTo', 'filterTestAccounts']] })),
    actions({
        readPerson: true,
        personRead: (person: PersonListItemApi | null) => ({ person }),
    }),
    reducers({
        person: [null as PersonListItemApi | null, { personRead: (_, { person }) => person }],
    }),
    selectors({
        range: [
            (s) => [s.dateFrom, s.dateTo, s.filterTestAccounts],
            (dateFrom: string, dateTo: string | null, filterTestAccounts: boolean): PersonRange =>
                personRange(dateFrom, dateTo, filterTestAccounts),
            { resultEqualityCheck: objectsEqual },
        ],
    }),
    listeners(({ actions, values, props, cache }) => ({
        readPerson: async () => {
            const readId = (cache.lastReadId = (cache.lastReadId ?? 0) + 1)
            const result = await readOrFailure(readPerson(props.personId, values.range))
            if (cache.disposables.isDisposed || cache.lastReadId !== readId) {
                return
            }
            actions.personRead('value' in result ? result.value : null)
        },
    })),
    // Fires on mount, then on each change of the range.
    subscriptions(({ actions }) => ({
        range: () => actions.readPerson(),
    })),
])
